import collections
from queue import PriorityQueue
import random

# Constants
LETTERS = ['a', 'b', 'c', 'd', 'e']


def task_func(string_length=100):
    if not isinstance(string_length, int) or isinstance(string_length, bool):
        raise TypeError("string_length must be an integer")
    if string_length < 0:
        raise ValueError("string_length must be non-negative")
    if not LETTERS:
        return collections.OrderedDict()

    generated = [random.choice(LETTERS) for _ in range(string_length)]
    counts = collections.Counter(generated)

    for letter in LETTERS:
        counts.setdefault(letter, 0)

    order_index = {letter: index for index, letter in enumerate(LETTERS)}
    items = sorted(counts.items(), key=lambda item: (-item[1], order_index.get(item[0], len(LETTERS))))

    return collections.OrderedDict(items)
